UPDATE zoning_districts SET far_regulated=FALSE, density_regulated=TRUE, pk1000_regulated=FALSE, ordinance_section='VERIFIED via independent re-fetch of the live Municode API (curl, 2026-07-24): Sec. 8.6.4.A reads verbatim ''The R-1 district provides for low density residential development at densities up to four dwelling units per acre, consistent with the RL future land use designation.'' Also independently confirmed Sec. 8.6.2 (the dimensional table) is genuinely just ''(See attachment [table] at end of chapter.)'' in the API content -- i.e. truly unreachable via this API, validating the researcher''s stated caveat rather than an excuse. Researcher''s figure and rationale confirmed CORRECT, no changes.' WHERE id=6840; -- 1138/R-1
