-- 2) Insert the 35 net-new zoning_districts rows
-- (id values below are the live-inserted ids from this session for FK reference
-- in step 3; a re-apply from a clean DB would need to look these up by code instead)
INSERT INTO zoning_districts (jurisdiction_id, code, name, category, far_regulated, density_regulated, pk1000_regulated, ordinance_section)
VALUES
  (897, 'R-1', 'RES (Residential)', 'residential', FALSE, TRUE, FALSE, 'VERIFIED via independent re-fetch of live Municode API (browser-header curl, 2026-07-24): Sec. 110-307(c)(4) states verbatim ''R-1: Six dwelling units per acre.'' Matches researcher''s reported value exactly. No FAR reference found anywhere in Sec. 110-307 text (grep for ''floor area ratio''/''F.A.R.'' returned zero matches), confirming far_applicable=false. Residential parking is per-unit per Sec. 110-811/110-828, confirming pk1000_applicable=false.'),
  (897, 'R-1A', 'RES (Residential)', 'residential', FALSE, TRUE, FALSE, 'Deltona Code of Ordinances Sec. 110-307, subsection (c) ''Maximum density'', item (3): explicit stated figure ''R-1A: Four dwelling units per acre'' (with community/public water and sewer). Same section covers R1-AAA/AA/A/R1 as a single classification group with a shared dimensional table (min lot size 9,500 sq ft, front yard 25 ft, height 35 ft, lot coverage 35%, min floor area 1,400 sq ft for R1-A). far_applicable=false: single-family district, no FAR anywhere in this section. pk1000_applicable=false per campaign rule (residential parking is per-unit, Sec. 110-811/110-828). [Not independently re-verified this pass -- adjacent R-1/R-1AA entries in same source doc were spot-checked and confirmed exact, giving high confidence this sibling entry from the identical section is also correct, but left unchanged per instructions to only correct/flag the 2 highest-count entries checked.]'),
  (897, 'R-1AA', 'RES (Residential)', 'residential', FALSE, TRUE, FALSE, 'VERIFIED as a byproduct of the R-1 re-fetch (same source document, same subsection (c)): Sec. 110-307(c)(2) states verbatim ''R-1AA: Three dwelling units per acre.'' Matches researcher''s reported value exactly. far_applicable=false and pk1000_applicable=false confirmed by same document-level checks as R-1 (no FAR text anywhere in section; residential parking is per-unit).'),
  (823, 'VC:B-43A', 'COM (Commercial)', 'unknown', FALSE, FALSE, FALSE, 'Code not found. Searched full text of DeLand''s current Code of Ordinances Ch. 33 (Land Development Regulations, all districts R-R through PD, all overlay/floating zones in Article IV including historic districts and gateway overlays) -- no district or code labeled ''VC'', ''VC:B-43A'', or ''B-43A'' exists anywhere in the current ordinance. Also checked Volusia County''s (unincorporated) ''Zoning Classification Summary Sheet'' PDF (volusia.org, dated 2012) which uses an entirely different naming scheme (R-1 through R-9, B-1 through B-9, MH-1 through MH-8, PUD) -- ''B-43A'' and ''VC'' do not appear there either. This code does not match any real, currently-codified DeLand or Volusia County zoning classification I could locate; it may be a legacy/historic pre-code designation, a malformed GIS parcel attribute, or a typo in source data. Leaving all fields null/false per BLANK > WRONG -- no ordinance basi'),
  (823, 'P-1&M', 'MIXED (Mixed Use)', 'unknown', FALSE, FALSE, FALSE, '''P-1&M'' is not itself a codified DeLand zoning classification -- it appears to be a GIS/parcel-data combination code denoting a parcel split between two separately codified districts: P-1 (Professional-Residential District) and M (likely M-1, Industrial District). DeLand''s ordinance has no single ''P-1&M'' or combined P-1/M-1 district with its own dimensional standards table, so I cannot apply the campaign''s suffix-substitution rule cleanly (that rule is for a single base code with an administrative letter suffix, not a two-district combination code covering possibly two different halves of one parcel). For reference only (not used to populate fields): P-1 alone states max NONresidential density as ''10,000 square feet of building per acre'' (an intensity metric, not a per-unit density or a true lot-based FAR) with no FAR stated; M-1 alone has no density field at all (nonresidential-only dis'),
  (938, 'RDD2', 'MIXED (Mixed Use)', 'redevelopment/downtown mixed-use', TRUE, TRUE, FALSE, 'NOT independently re-verified this session. Daytona Beach LDC Sec. 4.7.O (Redevelopment Downtown - Central Business District, coded ''RDD-2'' in the ordinance -- our GIS data''s ''RDD2'' is the same code without the hyphen, confidence 0.9 for this direct textual match). Ordinance table explicitly states ''Density, maximum: 40 du/ac'' and ''Floor area ratio (FAR), maximum: 10.0'' -- both used directly. pk1000_applicable=false: Sec. 4.7.O.4.a Modified Development Standards explicitly states ''Off-street parking is required for residential uses only'' for this district -- nonresidential/commercial uses in RDD-2 are exempt from off-street parking entirely, so there is no per-1,000sf ratio to report (not a gap, a genuine zero-requirement finding).'),
  (938, 'RDM6', 'MIXED (Mixed Use)', 'redevelopment/residential preservation', FALSE, TRUE, FALSE, 'NOT independently re-verified this session. Daytona Beach LDC Sec. 4.7.Z (Redevelopment Midtown - Residential Preservation, coded ''RDM-6'' in the ordinance -- our GIS data''s ''RDM6'' is the same code without the hyphen, confidence 0.9 for this direct textual match). Ordinance table states ''Density, maximum: n/a'' for the Single-Family Residential column but explicitly ''8 du/ac'' for the ''Other Residential Development'' column -- used directly per the explicit-stated-number rule (this is the district''s non-single-family residential track; single-family remains lot-size-governed at 5,000 sf min but that figure is identical between the two columns so 8 du/ac is reported as the district''s meaningful multi-unit cap). far_applicable=false: table shows FAR ''n/a'' for both Single-Family and Other Residential Development columns -- confirmed genuine non-applicability, not a gap. pk1000_applicable=false:'),
  (885, 'R-3M', 'RES (Residential)', 'residential', FALSE, TRUE, FALSE, 'VERIFIED via direct Municode backend API fetch (api.municode.com/CodesContent, ClientID 3932, productId 12297) bypassing the blocked library.municode.com JS shell. Sec.12(b)(1) text reads verbatim: ''Multifamily dwellings (12 units per gross acre maximum allowable density).'' Sec.27 table confirmed to show conflicting sub-row data (row H unified-ownership = dash; row i fee-simple = 2,000 sq.ft./D.U. = 21.78 du/acre) -- researcher correctly used the explicit Sec.12 stated cap of 12 rather than back-calculating. No FAR anywhere in Ch.17 confirmed. Original researcher note fully accurate.'),
  (885, 'R-8SF', 'RES (Residential)', 'residential', FALSE, TRUE, FALSE, 'VERIFIED via direct Municode backend API fetch (api.municode.com/CodesContent, ClientID 3932, productId 12297). Sec.27 Schedule of Dimensional Requirements table row for R-8SF confirmed: Minimum Lot Area/D.U. = ''8,000 sq. ft.'', Minimum Lot Width = 80 ft. 43,560/8,000 = 5.445 du/acre matches exactly. Original researcher note fully accurate.'),
  (885, 'RMH', 'RES (Residential)', 'residential', FALSE, TRUE, FALSE, 'Not independently re-verified this pass (spot-check budget spent on R-8SF/R-10SF/R-3M/RD). Original note internally consistent with the verified Sec.27 table structure (7,500 sq ft matches the pattern seen for R-7SF row). Left unchanged.'),
  (885, 'RD', 'COM (Commercial)', 'commercial/mixed-use', FALSE, TRUE, TRUE, 'VERIFIED via direct Municode backend API fetch (api.municode.com/CodesContent, ClientID 3932, productId 12297). Sec.25(b)(9) text reads verbatim: ''Multifamily dwellings (16 units per gross acre maximum allowable density) (subsection 14).'' Confirmed this is a special-exception use, not the district''s base use. Sec.25(a) purpose/intent confirmed verbatim: ''designed to encourage development... a mixture of office, commercial, warehouse/storage, and limited industrial uses.'' Sec.27 table row for RD shows Minimum Living Area/D.U.=dash and Minimum Lot Area/D.U.=''10,000 sq. ft.'' with footnote B, and footnote B is confirmed to read ''Minimum lot width and area apply to newly created lots'' -- i.e. a general lot-subdivision minimum, NOT a per-dwelling-unit density figure, which supports (does not contradict) the researcher''s claim that RD''s base table carries no residential density metric. Parking '),
  (885, 'PC-A', 'APUD (Agricultural PUD)', 'planned community', FALSE, TRUE, FALSE, 'Not independently re-verified this pass. Left unchanged.'),
